import json, glob, itertools, sys
from m2 import parse_fields, load
def pp(rs, V):
    rs=[list(r) for r in sorted(rs)]
    shifted=0
    i=0; n=len(rs)
    for i in range(n):
        j=i-shifted
        if j==0: continue
        prev=rs[j-1]; cur=rs[j]
        adj = cur[0] <= prev[1]+1 if V['ov'] else cur[0]==prev[1]+1
        if adj and cur[2]==prev[2]+1:
            prev[1]=max(prev[1],cur[1]); del rs[j]; shifted+=1
        else:
            cur[2]=max(cur[2]-shifted,0)
    return [tuple(r) for r in rs]
def core(rs, N=8):
    groups={}
    nxt=1
    for lo,hi,p in rs:
        st=max(lo,nxt)
        for k in range(st,min(hi,N)+1):
            groups.setdefault(p,[]).append(k)
        nxt=max(nxt,hi+1)
    res=[]
    for p in sorted(groups): res+=groups[p]
    return res
def hdr_ranges(hs):
    rs=[]
    for j,h in enumerate(hs):
        for i in h: rs.append((i,i,j))
    return rs
def model(c,V):
    f=pp(parse_fields(c['fields']),V) if c['fields'] else None
    if c['hs']:
        h=hdr_ranges(c['hs'])
        if V['hpp']: h=pp(h,V)
        if f is not None:
            h=h+f
            h=pp(h,V)
        elif V['hpp2']:
            h=pp(h,V)
        return core(h)
    return core(f)
if __name__=='__main__':
    for ov in [0,1]:
      for hpp in [0,1]:
        for hpp2 in [0,1]:
            V=dict(ov=ov,hpp=hpp,hpp2=hpp2)
