//! Minimal env_logger-compatible error logger.
use std::io::Write;
use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, PartialOrd, Debug)]
pub enum Level {
    Off = 0,
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

fn parse_level(s: &str) -> Option<Level> {
    match s.to_ascii_lowercase().as_str() {
        "off" => Some(Level::Off),
        "error" => Some(Level::Error),
        "warn" => Some(Level::Warn),
        "info" => Some(Level::Info),
        "debug" => Some(Level::Debug),
        "trace" => Some(Level::Trace),
        _ => None,
    }
}

struct Directive {
    name: Option<String>,
    level: Level,
}

static FILTER: OnceLock<Vec<Directive>> = OnceLock::new();

fn directives() -> &'static Vec<Directive> {
    FILTER.get_or_init(|| {
        let mut dirs = Vec::new();
        if let Ok(spec) = std::env::var("RUST_LOG") {
            let spec = spec.split('/').next().unwrap_or("");
            for part in spec.split(',').map(|s| s.trim()) {
                if part.is_empty() {
                    continue;
                }
                let mut it = part.split('=');
                let first = it.next().unwrap_or("");
                let second = it.next();
                if it.next().is_some() {
                    continue;
                }
                match second {
                    None => {
                        if let Some(l) = parse_level(first) {
                            dirs.push(Directive { name: None, level: l });
                        } else {
                            dirs.push(Directive { name: Some(first.to_string()), level: Level::Trace });
                        }
                    }
                    Some(lv) => {
                        let lv = lv.trim();
                        let level = if lv.is_empty() { Some(Level::Trace) } else { parse_level(lv) };
                        if let Some(level) = level {
                            if first.is_empty() {
                                dirs.push(Directive { name: None, level });
                            } else {
                                dirs.push(Directive { name: Some(first.to_string()), level });
                            }
                        }
                    }
                }
            }
        }
        if dirs.is_empty() {
            dirs.push(Directive { name: None, level: Level::Error });
        }
        dirs
    })
}

fn enabled(target: &str, level: Level) -> bool {
    // Most specific (longest) matching directive wins, later ones win ties.
    let mut best: Option<(usize, Level)> = None;
    for d in directives() {
        match &d.name {
            None => {
                if best.map_or(true, |(len, _)| len == 0) {
                    best = Some((0, d.level));
                }
            }
            Some(name) => {
                if target.starts_with(name.as_str()) {
                    let len = name.len();
                    if best.map_or(true, |(l, _)| len >= l) {
                        best = Some((len, d.level));
                    }
                }
            }
        }
    }
    match best {
        Some((_, l)) => level <= l && level != Level::Off,
        None => false,
    }
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

