//! Field range parsing and post processing.

/// Maximum value for an open ended range (kept below usize::MAX so `+1` never overflows).
pub const MAX: usize = usize::MAX - 1;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct FieldRange {
    /// 1-based, inclusive
    pub low: usize,
    /// 1-based, inclusive
    pub high: usize,
    pub pos: usize,
}

#[derive(Debug)]
pub enum FieldError {
    NumberedFromOne(usize),
    WrongOrder(String),
    Parse(String),
    NoHeadersMatched,
    HeaderNotFound(String),
}

impl std::fmt::Display for FieldError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            FieldError::NumberedFromOne(n) => write!(f, "Fields and positions are numbered from 1: {}", n),
            FieldError::WrongOrder(s) => write!(f, "High end of range less than low end of range: {}", s),
            FieldError::Parse(s) => write!(f, "Failed to parse field: {}", s),
            FieldError::NoHeadersMatched => write!(f, "No headers matched"),
            FieldError::HeaderNotFound(s) => write!(f, "Header not found: {}", s),
        }
    }
}

fn parse_num(s: &str) -> Option<usize> {
    s.parse::<usize>().ok()
}

/// Parse a list of fields like `1,3-5,7-,-9`.
pub fn parse_list(list: &str) -> Result<Vec<FieldRange>, FieldError> {
    let mut ranges = Vec::new();
    for (pos, item) in list.split(',').enumerate() {
        let mut parts = item.splitn(2, '-');
        let first = parts.next().unwrap_or("");
        let second = parts.next();
        let r = match second {
            None => match parse_num(first) {
                Some(0) => return Err(FieldError::NumberedFromOne(0)),
                Some(n) => FieldRange { low: n, high: n, pos },
                None => return Err(FieldError::Parse(item.to_string())),
            },
            Some(m) if m.is_empty() => match parse_num(first) {
                Some(0) => return Err(FieldError::NumberedFromOne(0)),
                Some(n) => FieldRange { low: n, high: MAX, pos },
                None => return Err(FieldError::Parse(first.to_string())),
            },
            Some(m) if first.is_empty() => match parse_num(m) {
                Some(0) => return Err(FieldError::NumberedFromOne(0)),
                Some(n) => FieldRange { low: 1, high: n, pos },
                None => return Err(FieldError::Parse(m.to_string())),
            },
            Some(m) => match (parse_num(first), parse_num(m)) {
                (Some(low), Some(high)) => {
                    if low == 0 {
                        return Err(FieldError::NumberedFromOne(0));
                    } else if low > high {
                        return Err(FieldError::WrongOrder(item.to_string()));
                    } else {
                        FieldRange { low, high, pos }
                    }
                }
                _ => return Err(FieldError::Parse(item.to_string())),
            },
        };
        ranges.push(r);
    }
    Ok(ranges)
}

/// Sort and merge ranges.
pub fn post_process(ranges: &mut Vec<FieldRange>) {
    ranges.sort();
    let mut shifted = 0usize;
    let len = ranges.len();
    for i in 0..len {
        let j = i - shifted;
        if j == 0 {
            continue;
        }
        let prev = ranges[j - 1];
        let cur = ranges[j];
        if cur.low <= prev.high + 1 && cur.pos.saturating_sub(1) == prev.pos {
            ranges[j - 1].high = prev.high.max(cur.high);
            ranges.remove(j);
            shifted += 1;
        } else {
            ranges[j].pos = cur.pos.saturating_sub(shifted);
        }
    }
}

/// Remove excluded ranges from the field ranges (both already post processed).
pub fn exclude(fields: &[FieldRange], excludes: &[FieldRange]) -> Vec<FieldRange> {
    let mut out = Vec::new();
    let mut k = 0usize;
    for f in fields {
        let (lo, hi, p) = (f.low, f.high, f.pos);
        let mut cur = lo;
        while k < excludes.len() && excludes[k].low <= hi {
            let elo = excludes[k].low;
            let ehi = excludes[k].high;
            if ehi < cur {
                k += 1;
                continue;
            }
            if elo > cur {
                out.push(FieldRange { low: cur, high: elo - 1, pos: p });
            }
            cur = cur.max(ehi.saturating_add(1));
            if ehi < hi {
                k += 1;
            } else {
                break;
            }
        }
        if cur <= hi {
            out.push(FieldRange { low: cur, high: hi, pos: p });
        }
    }
    out
}

/// Build ranges from a header line.
pub fn from_header_list(
    list: &[regex::Regex],
    header_fields: &[&[u8]],
    is_regex: bool,
    allow_missing: bool,
) -> Result<Vec<FieldRange>, FieldError> {
    let mut ranges = Vec::new();
    let mut found = vec![false; list.len()];
    let bytes_res: Vec<Option<regex::bytes::Regex>> = if is_regex {
        list.iter().map(|r| regex::bytes::Regex::new(r.as_str()).ok()).collect()
    } else {
        Vec::new()
    };
    for (i, field) in header_fields.iter().enumerate() {
        for (j, re) in list.iter().enumerate() {
            let matched = if is_regex {
                match &bytes_res[j] {
                    Some(b) => b.is_match(field),
                    None => false,
                }
            } else {
                re.as_str().as_bytes() == *field
            };
            if matched {
                found[j] = true;
                ranges.push(FieldRange { low: i + 1, high: i + 1, pos: j });
            }
        }
    }
    if !allow_missing {
        if ranges.is_empty() {
            return Err(FieldError::NoHeadersMatched);
        }
        for (j, f) in found.iter().enumerate() {
            if !f {
                return Err(FieldError::HeaderNotFound(list[j].as_str().to_string()));
            }
        }
    }
    post_process(&mut ranges);
    Ok(ranges)
}
