//! BGZF output writer using the system libdeflate when available.
use std::io::{self, Write};

pub const BLOCK_SIZE: usize = 65280;

type AllocFn = unsafe extern "C" fn(i32) -> *mut libc::c_void;
type CompressFn = unsafe extern "C" fn(*mut libc::c_void, *const u8, usize, *mut u8, usize) -> usize;

struct LibDeflate {
    compressor: *mut libc::c_void,
    compress: CompressFn,
}

fn load_libdeflate(level: u32) -> Result<Option<LibDeflate>, ()> {
    let names: [&[u8]; 3] = [b"libdeflate.so.0\0", b"libdeflate.so\0", b"/usr/lib/x86_64-linux-gnu/libdeflate.so.0\0"];
    for name in names.iter() {
        unsafe {
            let h = libc::dlopen(name.as_ptr() as *const libc::c_char, libc::RTLD_NOW);
            if h.is_null() {
                continue;
            }
            let a = libc::dlsym(h, b"libdeflate_alloc_compressor\0".as_ptr() as *const libc::c_char);
            let c = libc::dlsym(h, b"libdeflate_deflate_compress\0".as_ptr() as *const libc::c_char);
            if a.is_null() || c.is_null() {
                continue;
            }
            let alloc: AllocFn = std::mem::transmute(a);
            let compress: CompressFn = std::mem::transmute(c);
            if level > 12 {
                return Err(());
            }
            let comp = alloc(level as i32);
            if comp.is_null() {
                return Err(());
            }
            return Ok(Some(LibDeflate { compressor: comp, compress }));
        }
    }
    Ok(None)
}

pub struct BgzfWriter<W: Write> {
    inner: W,
    buffer: Vec<u8>,
    level: u32,
    lib: Option<LibDeflate>,
    blocks_written: usize,
    out: Vec<u8>,
}

fn panic_invalid() -> ! {
    eprintln!();
    eprintln!("thread 'main' panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/gzp-2.0.2/src/bgzf.rs:127:80:");
    eprintln!("called `Result::unwrap()` on an `Err` value: InvalidValue");
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    std::process::exit(101);
}

impl<W: Write> BgzfWriter<W> {
    pub fn new(inner: W, level: u32) -> Self {
        let lib = match load_libdeflate(level) {
            Ok(l) => l,
            Err(()) => panic_invalid(),
        };
        if lib.is_none() && level > 12 {
            panic_invalid();
        }
        BgzfWriter { inner, buffer: Vec::with_capacity(BLOCK_SIZE * 2), level, lib, blocks_written: 0, out: Vec::new() }
    }

    fn xfl(&self) -> u8 {
        if self.level <= 1 {
            4
        } else if self.level >= 9 {
            2
        } else {
            0
        }
    }

    fn deflate(&mut self, data: &[u8]) -> Vec<u8> {
        if let Some(lib) = &self.lib {
            let cap = data.len() + data.len() / 8 + 1024;
            let mut out = vec![0u8; cap];
            let n = unsafe { (lib.compress)(lib.compressor, data.as_ptr(), data.len(), out.as_mut_ptr(), out.len()) };
            if n > 0 {
                out.truncate(n);
                return out;
            }
        }
        let lvl = self.level.min(9);
        let mut enc = flate2::write::DeflateEncoder::new(Vec::new(), flate2::Compression::new(lvl));
        let _ = enc.write_all(data);
        enc.finish().unwrap_or_default()
    }

    fn write_block(&mut self, data: &[u8]) -> io::Result<()> {
        let cdata = self.deflate(data);
        let mut crc = crc32fast::Hasher::new();
        crc.update(data);
        let crc = crc.finalize();
        let total = 18 + cdata.len() + 8;
        self.out.clear();
        self.out.extend_from_slice(&[0x1f, 0x8b, 0x08, 0x04, 0, 0, 0, 0, self.xfl(), 0xff, 6, 0, b'B', b'C', 2, 0]);
        self.out.extend_from_slice(&((total - 1) as u16).to_le_bytes());
        self.out.extend_from_slice(&cdata);
        self.out.extend_from_slice(&crc.to_le_bytes());
        self.out.extend_from_slice(&(data.len() as u32).to_le_bytes());
        self.inner.write_all(&self.out)?;
        self.blocks_written += 1;
        Ok(())
    }

    pub fn finish(&mut self) -> io::Result<()> {
        if !self.buffer.is_empty() || self.blocks_written == 0 {
            let data = std::mem::take(&mut self.buffer);
            self.write_block(&data)?;
        }
        self.inner.write_all(&[
            0x1f, 0x8b, 0x08, 0x04, 0, 0, 0, 0, 0, 0xff, 6, 0, b'B', b'C', 2, 0, 0x1b, 0, 3, 0, 0, 0, 0, 0, 0, 0, 0, 0,
        ])?;
        self.inner.flush()
    }
}

