//! Input handling: files, stdin, decompression.
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdout, Command, Stdio};

pub struct CommandReader {
    child: Child,
    stdout: ChildStdout,
    stderr_thread: Option<std::thread::JoinHandle<Vec<u8>>>,
    done: bool,
}

impl CommandReader {
    fn close(&mut self) -> io::Result<()> {
        if self.done {
            return Ok(());
        }
        self.done = true;
        let status = self.child.wait()?;
        let stderr = match self.stderr_thread.take() {
            Some(t) => t.join().unwrap_or_default(),
            None => Vec::new(),
        };
        if status.success() {
            return Ok(());
        }
        let msg = String::from_utf8_lossy(&stderr);
        let text = if msg.trim().is_empty() {
            "<stderr is empty>".to_string()
        } else {
            let div: String = std::iter::repeat('-').take(79).collect();
            format!("\n{}\n{}\n{}", div, msg.trim(), div)
        };
        Err(io::Error::new(io::ErrorKind::Other, text))
    }
}

impl Read for CommandReader {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if self.done {
            return Ok(0);
        }
        let n = self.stdout.read(buf)?;
        if n == 0 {
            self.close()?;
        }
        Ok(n)
    }
}

fn decompression_command(path: &Path) -> Option<(&'static str, Vec<&'static str>)> {
    let name = path.to_string_lossy();
    let rules: &[(&[&str], &str, &[&str])] = &[
        (&[".gz", ".tgz"], "gzip", &["-d", "-c"]),
        (&[".bz2", ".tbz2"], "bzip2", &["-d", "-c"]),
        (&[".xz", ".txz"], "xz", &["-d", "-c"]),
        (&[".lz4"], "lz4", &["-d", "-c"]),
        (&[".lzma"], "xz", &["--format=lzma", "-d", "-c"]),
        (&[".br"], "brotli", &["-d", "-c"]),
        (&[".zst", ".zstd"], "zstd", &["-q", "-d", "-c"]),
        (&[".Z"], "uncompress", &["-c"]),
    ];
    // Last matching rule wins (as in grep-cli's matcher).
    let mut found = None;
    for (exts, cmd, args) in rules {
        for e in exts.iter() {
            if name.ends_with(e) {
                found = Some((*cmd, args.to_vec()));
            }
        }
    }
    found
}

/// Open a path for reading, optionally decompressing.
pub fn open_path(path: &Path, decompress: bool) -> io::Result<Box<dyn Read>> {
    if decompress {
        if path.extension().map(|e| e == "gz").unwrap_or(false) {
            let f = File::open(path)?;
            check_readable(&f)?;
            return Ok(Box::new(flate2::read::MultiGzDecoder::new(BufReader::with_capacity(128 * 1024, f))));
        }
        if let Some((cmd, args)) = decompression_command(path) {
            let mut c = Command::new(cmd);
            c.args(&args).arg(path).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());
            match c.spawn() {
                Ok(mut child) => {
                    let stdout = child.stdout.take().unwrap();
                    let mut stderr = child.stderr.take().unwrap();
                    let t = std::thread::spawn(move || {
                        let mut v = Vec::new();
                        let _ = stderr.read_to_end(&mut v);
                        v
                    });
                    return Ok(Box::new(CommandReader { child, stdout, stderr_thread: Some(t), done: false }));
                }
                Err(e) => {
                    crate::logger::debug(
                        "grep_cli::decompress",
                        &format!(
                            "{}: error spawning command '{:?} {}': {} (falling back to uncompressed reader)",
                            path.display(),
                            cmd,
                            args.iter().map(|a| format!("{:?}", a)).chain(std::iter::once(format!("{:?}", path.to_string_lossy()))).collect::<Vec<_>>().join(" "),
                            e
                        ),
                    );
                }
            }
        }
    }
    let f = File::open(path)?;
    check_readable(&f)?;
    Ok(Box::new(f))
}

fn check_readable(f: &File) -> io::Result<()> {
    let md = f.metadata()?;
    if md.is_dir() {
        return Err(io::Error::from_raw_os_error(libc::EISDIR));
    }
    Ok(())
}

pub enum Input {
    Stdin,
    Path(PathBuf),
}

impl Input {
    pub fn from(p: &PathBuf) -> Input {
        if p.as_os_str() == "-" {
            Input::Stdin
        } else {
            Input::Path(p.clone())
        }
    }
}

/// Line reader yielding lines including their terminator.
pub struct LineReader {
    inner: BufReader<Box<dyn Read>>,
}

impl LineReader {
    pub fn new(r: Box<dyn Read>) -> Self {
        LineReader { inner: BufReader::with_capacity(256 * 1024, r) }
    }
    /// Reads the next line (with terminator) into buf. Returns false at EOF.
    pub fn next_line(&mut self, buf: &mut Vec<u8>) -> io::Result<bool> {
        buf.clear();
        let n = self.inner.read_until(b'\n', buf)?;
        Ok(n > 0)
    }
}

/// Strip the line terminator from a raw line.
pub fn strip_line(line: &[u8], crlf: bool) -> &[u8] {
    if crlf {
        if line.ends_with(b"\r\n") {
            &line[..line.len() - 2]
        } else {
            line
        }
    } else if line.ends_with(b"\n") {
        &line[..line.len() - 1]
    } else {
        line
    }
}
