                        if !f(last, i) {
                            return;
                        }
                        last = i;
                    }
                    f(last, line.len());
                    return;
                }
                for s in memchr::memmem::find_iter(line, needle.as_slice()) {
                    if !f(last, s) {
                        return;
                    }
                    last = s + needle.len();
                }
                f(last, line.len());
            }
            Splitter::Byte(b) => {
                let mut last = 0usize;
                for s in memchr::memchr_iter(*b, line) {
                    if !f(last, s) {
                        return;
                    }
                    last = s + 1;
                }
                f(last, line.len());
            }
        }
    }

    pub fn split<'a>(&self, line: &'a [u8]) -> Vec<&'a [u8]> {
        let mut v = Vec::new();
        self.for_each_field(line, |s, e| {
            v.push(&line[s..e]);
            true
        });
        v
    }
}

pub struct Processor<'a> {
    pub fields: &'a [FieldRange],
    pub splitter: &'a Splitter,
    pub out_delim: &'a [u8],
    pub terminator: &'a [u8],
    shuffler: Vec<Vec<(usize, usize)>>,
    pos_sorted: bool,
    fast: bool,
}

impl<'a> Processor<'a> {
    pub fn new(fields: &'a [FieldRange], splitter: &'a Splitter, out_delim: &'a [u8], terminator: &'a [u8]) -> Self {
        let max_pos = fields.iter().map(|f| f.pos).max().unwrap_or(0);
        let pos_sorted = fields.windows(2).all(|w| w[0].pos <= w[1].pos);
        let fast = matches!(splitter, Splitter::Byte(_));
        Processor { fields, splitter, out_delim, terminator, shuffler: vec![Vec::new(); max_pos + 1], pos_sorted, fast }
    }

    fn collect_general(&mut self, line: &[u8]) {
        let fields = self.fields;
        let shuffler = &mut self.shuffler;
        let mut ri = 0usize; // current range index
        let mut idx = 0usize; // 1-based index of the field being delivered
        // Skip ranges that are already fully consumed.
        let mut next = 1usize; // next unconsumed field index
        if fields.is_empty() {
            return;
        }
        self.splitter.for_each_field(line, |s, e| {
            idx += 1;
            loop {
                if ri >= fields.len() {
                    return false;
                }
                let r = &fields[ri];
                let start = r.low.max(next);
                if start > r.high {
                    ri += 1;
                    continue;
                }
                if idx < start {
                    // skip this field
                    return true;
                }
                // idx >= start and idx <= high guaranteed since we only move forward one at a time
                shuffler[r.pos].push((s, e));
                next = idx + 1;
                if idx >= r.high {
                    ri += 1;
                }
                return true;
            }
        });
    }

    fn collect_fast_sorted(&mut self, line: &[u8]) {
        let fields = self.fields;
        let shuffler = &mut self.shuffler;
        let last_high = match fields.last() {
            Some(l) => l.high,
            None => return,
        };
        let mut idx = 0usize;
        self.splitter.for_each_field(line, |s, e| {
            idx += 1;
            if idx > last_high {
                return false;
            }
            for r in fields {
                if r.low <= idx && idx <= r.high {
                    shuffler[r.pos].push((s, e));
                }
            }
            true
        });
    }

    pub fn process_line<W: Write>(&mut self, line: &[u8], general: bool, out: &mut W) -> io::Result<()> {
        if self.fast && self.pos_sorted && !general {
            self.collect_fast_sorted(line);
        } else {
            self.collect_general(line);
        }
        let mut first = true;
        for g in self.shuffler.iter_mut() {
            for &(s, e) in g.iter() {
                if !first {
                    out.write_all(self.out_delim)?;
                }
                first = false;
                out.write_all(&line[s..e])?;
            }
            g.clear();
        }
        out.write_all(self.terminator)?;
        Ok(())
    }
}
