            RunError::Io(e) => write!(f, "{}", e),
            RunError::Field(e) => write!(f, "{}", e),
        }
    }
}

struct Opts {
    splitter: Splitter,
    out_delim: Vec<u8>,
    terminator: Vec<u8>,
    crlf: bool,
    fields: Option<Vec<FieldRange>>,
    excludes: Vec<FieldRange>,
    header_fields: Vec<regex::Regex>,
    exclude_headers: Vec<regex::Regex>,
    header_is_regex: bool,
    decompress: bool,
}

impl Opts {
    fn need_header(&self) -> bool {
        !self.header_fields.is_empty() || !self.exclude_headers.is_empty()
    }

    fn compute_fields(&self, header: Option<&[u8]>) -> Result<Vec<FieldRange>, FieldError> {
        let header_parts: Vec<&[u8]> = match header {
            Some(h) => {
                let content = input::strip_line(h, self.crlf);
                self.splitter.split(content)
            }
            None => Vec::new(),
        };
        let mut fields = if !self.header_fields.is_empty() {
            let mut h = fields::from_header_list(&self.header_fields, &header_parts, self.header_is_regex, false)?;
            if let Some(f) = &self.fields {
                h.extend_from_slice(f);
                fields::post_process(&mut h);
            }
            h
        } else if let Some(f) = &self.fields {
            f.clone()
        } else {
            vec![FieldRange { low: 1, high: MAX, pos: 0 }]
        };
        let mut ex = self.excludes.clone();
        if !self.exclude_headers.is_empty() {
            let eh = fields::from_header_list(&self.exclude_headers, &header_parts, self.header_is_regex, true)?;
            ex.extend_from_slice(&eh);
            fields::post_process(&mut ex);
        }
        if !ex.is_empty() {
            fields = fields::exclude(&fields, &ex);
        }
        Ok(fields)
    }
}

fn read_first_line(r: Box<dyn Read>) -> io::Result<Option<Vec<u8>>> {
    let mut lr = LineReader::new(r);
    let mut buf = Vec::new();
    if lr.next_line(&mut buf)? {
        Ok(Some(buf))
    } else {
        Ok(None)
    }
}

fn process_lines<W: Write>(
    reader: &mut LineReader,
    proc_: &mut Processor,
    crlf: bool,
    out: &mut W,
) -> Result<(), RunError> {
    let mut buf = Vec::with_capacity(1024);
    while reader.next_line(&mut buf)? {
        let line = input::strip_line(&buf, crlf);
        proc_.process_line(line, false, out)?;
    }
    Ok(())
}

fn process_input<W: Write>(inp: &Input, opts: &Opts, out: &mut W) -> Result<(), RunError> {
    match inp {
        Input::Path(p) => {
            let header = if opts.need_header() {
                read_first_line(input::open_path(p, opts.decompress)?)?
            } else {
                None
            };
            let fields = opts.compute_fields(header.as_deref())?;
            if fields.is_empty() {
                return Ok(());
            }
            let mut reader = LineReader::new(input::open_path(p, opts.decompress)?);
            let mut proc_ = Processor::new(&fields, &opts.splitter, &opts.out_delim, &opts.terminator);
            process_lines(&mut reader, &mut proc_, opts.crlf, out)
        }
        Input::Stdin => {
            let stdin: Box<dyn Read> = Box::new(unsafe { File::from_raw_fd(0) });
            let stdin: Box<dyn Read> = if opts.decompress {
                Box::new(flate2::read::MultiGzDecoder::new(io::BufReader::with_capacity(128 * 1024, stdin)))
            } else {
                stdin
            };
            let mut reader = LineReader::new(stdin);
            if opts.need_header() {
                let mut hbuf = Vec::new();
                let has = reader.next_line(&mut hbuf)?;
                let header = if has { Some(hbuf.as_slice()) } else { None };
                let fields = opts.compute_fields(header)?;
                if fields.is_empty() {
                    return Ok(());
                }
                let mut proc_ = Processor::new(&fields, &opts.splitter, &opts.out_delim, &opts.terminator);
                if has {
                    let line = input::strip_line(&hbuf, opts.crlf);
                    proc_.process_line(line, true, out)?;
                }
                process_lines(&mut reader, &mut proc_, opts.crlf, out)
            } else {
                let fields = opts.compute_fields(None)?;
                if fields.is_empty() {
                    return Ok(());
                }
                let mut proc_ = Processor::new(&fields, &opts.splitter, &opts.out_delim, &opts.terminator);
                process_lines(&mut reader, &mut proc_, opts.crlf, out)
            }
        }
    }
}

struct RawOut {
    file: File,
}

impl Write for RawOut {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        self.file.write(buf)
    }
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

enum Sink {
    Plain(BufWriter<BufWriter<RawOut>>),
    Gz(BufWriter<bgzf::BgzfWriter<RawOut>>),
}

impl Write for Sink {
    #[inline]
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Sink::Plain(w) => w.write(buf),
            Sink::Gz(w) => w.write(buf),
        }
    }
    #[inline]
    fn write_all(&mut self, buf: &[u8]) -> io::Result<()> {
        match self {
            Sink::Plain(w) => w.write_all(buf),
            Sink::Gz(w) => w.write_all(buf),
        }
    }
    fn flush(&mut self) -> io::Result<()> {
        match self {
            Sink::Plain(w) => w.flush(),
            Sink::Gz(w) => w.flush(),
        }
    }
}

fn is_broken_pipe(e: &RunError) -> bool {
    matches!(e, RunError::Io(io) if io.kind() == io::ErrorKind::BrokenPipe)
}

fn exit_on_error(e: RunError) -> ! {
    if is_broken_pipe(&e) {
        std::process::exit(0);
    }
    logger::error(&e.to_string());
    std::process::exit(1);
}

fn main() {
    let matches = cli::build().get_matches();

    let inputs: Vec<PathBuf> = matches.get_many::<PathBuf>("input").map(|v| v.cloned().collect()).unwrap_or_default();
    let output: Option<PathBuf> = matches.get_one::<PathBuf>("output").cloned();
    let delimiter: String = matches.get_one::<String>("delimiter").cloned().unwrap_or_default();
    let delim_is_literal = matches.get_flag("delim_is_literal");
    let use_input_delim = matches.get_flag("use_input_delim");
    let output_delimiter: String = matches.get_one::<String>("output_delimiter").cloned().unwrap_or_default();
    let fields_s: Option<String> = matches.get_one::<String>("fields").cloned();
    let exclude_s: Option<String> = matches.get_one::<String>("exclude").cloned();
    let exclude_headers: Vec<regex::Regex> =
        matches.get_many::<regex::Regex>("exclude_header").map(|v| v.cloned().collect()).unwrap_or_default();
    let header_fields: Vec<regex::Regex> =
        matches.get_many::<regex::Regex>("header_field").map(|v| v.cloned().collect()).unwrap_or_default();
    let header_is_regex = matches.get_flag("header_is_regex");
    let try_decompress = matches.get_flag("try_decompress");
    let try_compress = matches.get_flag("try_compress");
    let _threads: usize = *matches.get_one::<usize>("compression_threads").unwrap_or(&4);
    let level: u32 = *matches.get_one::<u32>("compression_level").unwrap_or(&6);
    let crlf = matches.get_flag("crlf");

    // Open output.
    let raw = match &output {
        Some(path) => match File::create(path) {
            Ok(f) => RawOut { file: f },
            Err(e) => {
                eprintln!("Error: Failed to open {} for writing.\n\nCaused by:\n    {}", path.display(), e);
                std::process::exit(1);
            }
        },
        None => RawOut { file: unsafe { File::from_raw_fd(1) } },
    };

    // Delimiter.
    let unescaped_delim = unescape(&delimiter);
    let splitter = if delim_is_literal {
        if unescaped_delim.len() == 1 {
            Splitter::Byte(unescaped_delim[0])
        } else {
            Splitter::Substr(unescaped_delim.clone())
        }
    } else {
        match regex::bytes::Regex::new(&delimiter) {
            Ok(r) => Splitter::Regex(r),
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    };

    let out_delim = if use_input_delim && delim_is_literal { unescaped_delim.clone() } else { unescape(&output_delimiter) };

    // Fields
    let fields = match &fields_s {
        Some(s) => match fields::parse_list(s) {
            Ok(mut f) => {
                fields::post_process(&mut f);
                Some(f)
            }
            Err(e) => exit_on_error(RunError::Field(e)),
        },
        None => None,
    };
    let excludes = match &exclude_s {
        Some(s) => match fields::parse_list(s) {
            Ok(mut f) => {
                fields::post_process(&mut f);
                f
            }
            Err(e) => exit_on_error(RunError::Field(e)),
        },
        None => Vec::new(),
    };

    let opts = Opts {
        splitter,
        out_delim,
        terminator: if crlf { b"\r\n".to_vec() } else { b"\n".to_vec() },
        crlf,
        fields,
        excludes,
        header_fields,
        exclude_headers,
        header_is_regex,
        decompress: try_decompress,
    };

    let mut sink = if try_compress {
        Sink::Gz(BufWriter::with_capacity(8192, bgzf::BgzfWriter::new(raw, level)))
    } else {
        Sink::Plain(BufWriter::with_capacity(8192, BufWriter::with_capacity(8192, raw)))
    };

    let inputs: Vec<Input> = if inputs.is_empty() { vec![Input::Stdin] } else { inputs.iter().map(Input::from).collect() };

    for inp in &inputs {
        if let Err(e) = process_input(inp, &opts, &mut sink) {
            exit_on_error(e);
        }
    }

    let res = match sink {
        Sink::Plain(mut w) => w.flush(),
        Sink::Gz(w) => match w.into_inner() {
            Ok(mut g) => g.finish(),
            Err(e) => Err(e.into_error()),
        },
    };
    if let Err(e) = res {
        exit_on_error(RunError::Io(e));
    }
}
